actions.script:
let choices = null
try { choices = JSON.parse(ec.web.sessionAttributes.edgeSetup || 'null') } catch (e) { choices = null }
if (!choices) { ec.message.addError(ec.l10n.localize('Choose what to set up first, in Discover')); return }
const hostList = (choices.passthroughNames || []).map((hostName) => ({hostName, modeEnumId: 'EdgeHostPassthrough'}))
    .concat((choices.terminateNames || []).map((hostName) => ({hostName, modeEnumId: 'EdgeHostTerminate'})))
const out = ec.service.sync().name('org.moqui.edge.EdgeServices.apply#EdgeSetup').parameters({
    webOn: !!choices.webOn, hostList, mailOn: !!choices.mailOn, mailDomains: choices.mailDomains || [],
    systemMail: !!choices.systemMail, emailAccountIds: choices.emailAccountIds || [],
    chatOn: !!choices.chatOn, chatBridgeIds: choices.chatBridgeIds || [],
    passOn: !!choices.passOn, passSites: choices.passSites || [], passCallback: choices.passCallback || '',
    xmppOn: !!choices.xmppOn,
    // only a choice Discover offered: left out, this node's edge_calls_enabled stays as it is
    callsOn: choices.callsOffered ? !!choices.callsOn : null,
    // the same for phones: left out, edge_sip_enabled stays as it is
    sipOn: choices.sipOffered ? !!choices.sipOn : null}).call()
if (ec.message.hasError()) return
const lines = Array.from(out?.lineList || []).map((line) => ({area: line.area, ok: line.ok === true, text: line.text}))
const configured = out?.configured === true
ec.web.sessionAttributes.edgeApplied = JSON.stringify({lines, configured})
ec.web.sessionAttributes.remove('edgeTested')
const failed = lines.filter((line) => !line.ok).length
if (!configured) ec.message.addMessage(ec.l10n.localize('Not applied: the edge node did not take the setup, and nothing was changed here'), 'danger')
else if (failed) ec.message.addMessage(ec.resource.expand('Applied, with ${n} steps that did not go through', '', {n: failed}), 'warning')
else ec.message.addMessage(ec.l10n.localize('Applied: this node is set up with the edge node'), 'success')

let kept = null
try { kept = JSON.parse(ec.web.sessionAttributes.edgeApplied || 'null') } catch (e) { kept = null }
if (!kept?.configured) ec.message.addError(ec.l10n.localize('Apply the setup first'))

const L = (text) => ec.l10n.localize(text)
const link = ec.service.sync().name('org.moqui.edge.EdgeServices.get#LinkStatus').call() || {}
notBuilt = link.state === 'notBuilt'
notStarted = link.state === 'notStarted'
const running = !notBuilt && !notStarted
// an edge or all-in-one node takes links; the wizard is a local node's (plans/archive/Edge-Node.md §10)
isEdge = running && link.takesLinks === true
notPaired = running && !isEdge && (!link.state || link.state === 'unpaired')
let choices = null
try { choices = JSON.parse(ec.web.sessionAttributes.edgeSetup || 'null') } catch (e) { choices = null }
noChoices = running && !isEdge && !notPaired && !choices
ready = running && !isEdge && !notPaired && !!choices
lineList = []
recordList = []
dnsError = ''
applied = false
if (!ready) return
const list = (items) => Array.from(items || []).join(', ')
const hostNames = choices.webOn ? (choices.passthroughNames || []).concat(choices.terminateNames || []) : []
const accountText = choices.mailOn ? ec.resource.expand('${n} accounts', '', {n: (choices.emailAccountIds || []).length}) : ''
summary = {
    webText: choices.webOn ? [list(choices.passthroughNames) && list(choices.passthroughNames) + ' (' + L('passthrough') + ')',
        list(choices.terminateNames) && list(choices.terminateNames) + ' (' + L('terminate') + ')'].filter((text) => text).join('; ') : L('Off'),
    mailText: choices.mailOn ? list(choices.mailDomains) + (choices.systemMail ? '; ' + L('the system') + ', ' : '; ') + accountText : L('Off'),
    chatText: choices.chatOn ? ec.resource.expand('${n} bridges', '', {n: (choices.chatBridgeIds || []).length}) : L('Off'),
    passText: choices.passOn ? list(choices.passSites) + ' · ' + (choices.passCallback || '') : L('Off'),
    xmppText: choices.xmppOn ? choices.xmppDomain || '' : L('Off'),
    callsText: !choices.callsOffered ? L('Not offered, so left as it is')
        : choices.callsOn ? L("New calls on the edge node's media node") : L('Off'),
    sipText: !choices.sipOffered ? L('Not offered, so left as it is')
        : choices.sipOn ? L("This node's trunks and phones through the edge node's SIP engine") : L('Off')}
let kept = null
try { kept = JSON.parse(ec.web.sessionAttributes.edgeApplied || 'null') } catch (e) { kept = null }
applied = !!kept?.configured
const areaNames = {web: L('Web access'), mail: L('Mail'), chat: L('Chat'), pass: L('PASS'), xmpp: L('XMPP'),
    calls: L('Calls'), sip: L('Phones'), link: L('Link')}
lineList = Array.from(kept?.lines || []).map((line) => ({areaText: areaNames[line.area] || line.area, text: line.text,
    stateLabel: line.ok ? L('Done') : L('Not done'), stateColor: line.ok ? 'positive' : 'negative'}))
confirm = {applied: applied ? 'Y' : ''}
// the DNS records, checked live: the edge node's MX host, addresses and key come from its offer; each a probe
if (!hostNames.length && !choices.mailOn && !choices.xmppOn && !choices.callsOn && !choices.sipOn) return
ec.message.pushErrors()
try {
    const offered = ec.service.sync().name('org.moqui.edge.EdgeServices.get#EdgeOffer').call() || {}
    const offer = offered.offer || {}
    if (!ec.message.hasError()) {
        // the names an XMPP SRV record may point at: the edge node's own
        const urlHost = String(offered.edgeUrl || '').replace(/^[a-z]+:\/\//i, '').split(/[/:?#]/)[0].toLowerCase()
        // an SRV target is a host name, never an address
        const xmppHosts = Array.from(new Set(Array.from(offer.publicNames || []).concat([urlHost, offer.mail?.mxHost || ''])
            .map((name) => String(name).trim().replace(/^\[|\]$/g, '').replace(/\.$/, '').toLowerCase())
            .filter((name) => name && !name.includes(':') && !/^[0-9.]+$/.test(name))))
        // the hosts of the edge node's TURN URLs (turn:host:port?transport=..); check#EdgeDns leaves out addresses
        const turnHosts = choices.callsOn ? Array.from(offer.calls?.turnUrls || []).map((url) => {
            const authority = String(url).replace(/^turns?:/i, '').split('?')[0]
            return authority.startsWith('[') ? '' : authority.replace(/:\d*$/, '')
        }).filter((host) => host) : []
        const out = ec.service.sync().name('org.moqui.edge.EdgeServices.check#EdgeDns').parameters({
            domains: choices.mailOn ? choices.mailDomains || [] : [], hostNames,
            mxHost: offer.mail?.mxHost || '', edgeAddresses: offer.addresses || [],
            dkimSelector: offer.mail?.dkimSelector || '', dkimRecord: offer.mail?.dkimRecord || '',
            mailMta: offer.mail?.mta || '',
            xmppDomain: choices.xmppOn ? choices.xmppDomain || '' : '', xmppHosts,
            xmppPort: offer.xmpp?.port || 0, xmppTlsPort: offer.xmpp?.tlsPort || 0,
            turnHosts, mediaAddress: choices.callsOn ? offer.calls?.mediaAddress || '' : '',
            // the SIP domain's SRV records name the edge node's names (as XMPP's) and its SIP ports
            sipDomain: choices.sipOn && offer.sip?.available ? offer.sip.domain || '' : '', sipHosts: xmppHosts,
            sipPort: Number(String(offer.sip?.sipAddress || '').split(':').pop()) || 0,
            sipTlsPort: Number(String(offer.sip?.tlsAddress || '').split(':').pop()) || 0}).call() || {}
        recordList = Array.from(out.recordList || []).map((record) => ({kind: record.kind, name: record.name,
            expected: record.later ? '' : record.expected || '', found: record.found || (record.later ? '' : L('None')),
            note: record.note || '',
            stateLabel: record.later ? L('Not needed yet') : record.ok ? L('Set') : L('Not yet'),
            stateColor: record.later ? 'grey' : record.ok ? 'positive' : 'warning'}))
    }
    if (ec.message.hasError()) dnsError = ec.message.getErrorsString()
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
